132	void GeTensorSerializeUtils::GeTensorDescAsProto(const GeTensorDescImpl &desc, proto::TensorDescriptor *proto) {
133	  if (proto != nullptr) {
134	    // serialize extension tensor meta data
135	    proto->set_size(desc.ext_meta_.GetSize());
136	    proto->set_weight_size(desc.ext_meta_.GetWeightSize());
137	    proto->set_reuse_input(desc.ext_meta_.GetReuseInput());
138	    proto->set_output_tensor(desc.ext_meta_.GetOutputTensor());
139	    if (kDeviceToStrMap.find(desc.ext_meta_.GetDeviceType()) != kDeviceToStrMap.end()) {
140	      proto->set_device_type(kDeviceToStrMap.at(desc.ext_meta_.GetDeviceType()));
141	    }
142	    proto->set_input_tensor(desc.ext_meta_.GetInputTensor());
143	    proto->set_real_dim_cnt(static_cast<int64_t>(desc.ext_meta_.GetRealDimCnt()));
144	    proto->set_reuse_input_index(static_cast<int64_t>(desc.ext_meta_.GetReuseInputIndex()));
145	    proto->set_data_offset(desc.ext_meta_.GetDataOffset());
146	    proto->set_cmps_size(desc.ext_meta_.GetCmpsSize());
147	    proto->set_cmps_tab(desc.ext_meta_.GetCmpsTab());
148	    proto->set_cmps_tab_offset(desc.ext_meta_.GetCmpsTabOffset());
149	
150	    // serialize attributes
151	    if (!ModelSerializeImp::SerializeAllAttrsFromAnyMap(desc.attrs_.GetAllAttrs(), proto->mutable_attr())) {
152	      GELOGE(GRAPH_FAILED, "GeTensorDesc attr serialize failed.");
153	      return;
154	    }
155	
156	    if (!desc.attrs_.GetAttrsGroupPtr().empty()) {
157	      // serialize Attr Group
158	      if (AttrGroupSerialize::SerializeAllAttr(*(proto->mutable_attr_groups()), desc.attrs_) != af::SUCCESS) {
159	        GELOGE(GRAPH_FAILED, "GeTensorDesc attr serialize failed.");
160	        return;
161	      }
162	    }
163	
164	    // serialize member object
165	    (*proto->mutable_attr())[TENSOR_UTILS_ORIGIN_FORMAT].set_s(TypeUtils::FormatToSerialString(desc.GetOriginFormat()));
166	
167	    (*proto->mutable_attr())[TENSOR_UTILS_ORIGIN_FORMAT_INT].set_i(desc.GetOriginFormat());
168	
169	    (*proto->mutable_attr())[TENSOR_UTILS_FORMAT].set_i(desc.GetFormat());
170	
171	    if (desc.GetOriginDataType() != DT_UNDEFINED) {
172	      (*proto->mutable_attr())[TENSOR_UTILS_ORIGIN_DATA_TYPE].set_s(
173	          TypeUtils::DataTypeToSerialString(desc.GetOriginDataType()));
174	    }
175	
176	    const bool is_origin_shape_init = desc.ext_meta_.IsOriginShapeInited();
177	    (*proto->mutable_attr())[TENSOR_UTILS_ORIGIN_SHAPE_INITIALIZED].set_b(is_origin_shape_init);
178	    if (is_origin_shape_init) {
179	      auto const origin_shape_proto_list = (*proto->mutable_attr())[TENSOR_UTILS_ORIGIN_SHAPE].mutable_list();
180	      origin_shape_proto_list->clear_i();
181	      for (auto const dim : desc.OriginShapeReference().GetDims()) {
182	        origin_shape_proto_list->add_i(dim);
183	      }
184	      origin_shape_proto_list->set_val_type(proto::AttrDef::ListValue::VT_LIST_INT);
185	    }
186	
187	    auto const iter = kDataTypeMap.find(desc.GetDataType());
188	    if (iter != kDataTypeMap.end()) {
189	      proto->set_dtype(iter->second);
190	    } else {  // maybe custom data type
191	      proto->set_dtype(kDataTypeMap.at(DT_UNDEFINED));
192	    }
193	    proto->set_layout(TypeUtils::FormatToSerialString(desc.GetFormat()));
194	    GeTensorSerializeUtils::GeShapeAsProto(desc.ShapeReference(), proto->mutable_shape());
195	  }
196	}
197	void GeTensorSerializeUtils::GeTensorDescAsProto(const GeTensorDesc &desc, proto::TensorDescriptor *proto) {
