200	void GeTensorSerializeUtils::GeTensorAsProto(const GeTensorImpl &tensor, proto::TensorDef *proto) {
201	  if (tensor.tensor_def_.protoOwner_ != nullptr) {
202	    if (tensor.tensor_def_.protoMsg_ != nullptr) {
203	      *proto = *tensor.tensor_def_.protoMsg_;
204	      GeTensorDescAsProto(tensor.desc_, proto->mutable_desc());
205	    }
206	  } else {
207	    if ((tensor.tensor_data_.impl_ != nullptr) && (tensor.tensor_data_.impl_->tensor_descriptor_ != nullptr)) {
208	      GeTensorDescAsProto(*tensor.tensor_data_.impl_->tensor_descriptor_, proto->mutable_desc());
209	    }
210	    proto->set_data(tensor.tensor_data_.data(), tensor.tensor_data_.size());
211	  }
212	}
