234	void GeTensorSerializeUtils::NormalizeGeTensorDescProto(proto::TensorDescriptor *proto) {
235	  if (proto == nullptr) {
236	    return;
237	  }
238	  auto &attr_map = *(proto->mutable_attr());
239	  auto iter = attr_map.find(TENSOR_UTILS_SIZE);
240	  if (iter != attr_map.end()) {
241	    proto->set_size(iter->second.i());
242	  }
243	  iter = attr_map.find(TENSOR_UTILS_WEIGHT_SIZE);
244	  if (attr_map.end() != iter) {
245	    proto->set_weight_size(iter->second.i());
246	  }
247	  iter = attr_map.find(TENSOR_UTILS_REUSE_INPUT);
248	  if (attr_map.end() != iter) {
249	    proto->set_reuse_input(iter->second.b());
250	  }
251	  iter = attr_map.find(TENSOR_UTILS_OUTPUT_TENSOR);
252	  if (attr_map.end() != iter) {
253	    proto->set_output_tensor(iter->second.b());
254	  }
255	  iter = attr_map.find(TENSOR_UTILS_DEVICE_TYPE);
256	  if (attr_map.end() != iter) {
257	    proto->set_device_type(iter->second.s());
258	  }
259	  iter = attr_map.find(TENSOR_UTILS_INPUT_TENSOR);
260	  if (attr_map.end() != iter) {
261	    proto->set_input_tensor(iter->second.b());
262	  }
263	  iter = attr_map.find(TENSOR_UTILS_REAL_DIM_CNT);
264	  if (attr_map.end() != iter) {
265	    proto->set_real_dim_cnt(iter->second.i());
266	  }
267	  iter = attr_map.find(TENSOR_UTILS_REUSE_INPUT_INDEX);
268	  if (attr_map.end() != iter) {
269	    proto->set_reuse_input_index(iter->second.i());
270	  }
271	  iter = attr_map.find(TENSOR_UTILS_DATA_OFFSET);
272	  if (attr_map.end() != iter) {
273	    proto->set_data_offset(iter->second.i());
274	  }
275	  iter = attr_map.find(TENSOR_UTILS_CMPS_SIZE);
276	  if (attr_map.end() != iter) {
277	    proto->set_cmps_size(iter->second.i());
278	  }
279	  iter = attr_map.find(TENSOR_UTILS_CMPS_TAB);
280	  if (attr_map.end() != iter) {
281	    proto->set_cmps_tab(iter->second.s());
282	  }
283	  iter = attr_map.find(TENSOR_UTILS_CMPS_TAB_OFFSET);
284	  if (attr_map.end() != iter) {
285	    proto->set_cmps_tab_offset(iter->second.i());
286	  }
287	}
