315	void GeTensorSerializeUtils::GetDtypeFromDescProto(const proto::TensorDescriptor *const proto, DataType &dtype) {
316	  if (proto == nullptr) {
317	    return;
318	  }
319	  dtype = DT_UNDEFINED;
320	  auto &attrs = proto->attr();
321	  auto const iter = attrs.find(kKeyDataTypeSelfDefined);
322	  if (iter == attrs.end()) {
323	    auto const proto_dtype = proto->dtype();
324	    auto const founded = std::find_if(
325	        kDataTypeMap.begin(), kDataTypeMap.end(),
326	        [proto_dtype](const std::pair<DataType, af::proto::DataType> &item) { return item.second == proto_dtype; });
327	    if (founded != kDataTypeMap.end()) {
328	      dtype = founded->first;
329	      return;
330	    }
331	  } else {  // Custom defined data type set
332	    const int64_t data_type_proto = iter->second.i();
333	    auto const founded = std::find_if(
334	        kDataTypeSelfDefinedMap.begin(), kDataTypeSelfDefinedMap.end(),
335	        [data_type_proto](const std::pair<DataType, int> &item) { return item.second == data_type_proto; });
336	    if (founded != kDataTypeSelfDefinedMap.end()) {
337	      dtype = founded->first;
338	      return;
339	    }
340	  }
341	}
