477	std::string GeShapeImpl::ShapeImplToString() const {
478	  if (dims_.empty()) {
479	    return "";
480	  }
481	
482	  std::stringstream ss;
483	  ss << dims_[0UL];
484	  for (size_t i = 1UL; i < dims_.size(); i++) {
485	    ss << "," << dims_[i];
486	  }
487	  return ss.str();
