490	int64_t GeShapeImpl::GetShapeSize() const {
491	  if (dims_.empty()) {
492	    return 0;
493	  }
494	  int64_t shape_size = 1;
495	  for (auto const dim : dims_) {
496	    if ((dim == UNKNOWN_DIM) || (dim == UNKNOWN_DIM_NUM) || (dim < 0)) {
497	      return -1;
498	    } else if (dim == 0) {
499	      return 0;
500	    } else {
501	      if (shape_size > (INT64_MAX / dim)) {
502	        return -1;
503	      }
504	      shape_size *= dim;
505	    }
506	  }
507	  return shape_size;
508	}
