631	GeTensorDescImpl::GeTensorDescImpl(proto::TensorDescriptor *const proto_msg) : GeTensorDescImpl() {
632	  if (proto_msg == nullptr) {
633	    GELOGE(INTERNAL_ERROR, "Try assemble ge tensor desc from nullptr proto");
634	    return;
635	  }
636	  // normalize the input TensorDescriptor，A metadata information maybe stored in different fields of TensorDescriptor,
637	  // This function needs to prioritize and determine the final metadata information used.
638	  // After standardization, the direct member field on TensorDescriptor is always valid
639	  GeTensorSerializeUtils::NormalizeGeTensorDescProto(proto_msg);
640	
641	  // store high frequency attributes to member field
642	  GeTensorSerializeUtils::GetOriginFormatFromDescProto(proto_msg, origin_format_);
643	  GeTensorSerializeUtils::GetOriginDtypeFromDescProto(proto_msg, origin_dtype_);
644	  GeTensorSerializeUtils::GetOriginShapeFromDescProto(proto_msg, origin_shape_);
645	
646	  GeTensorSerializeUtils::GetFormatFromDescProto(proto_msg, format_);
647	  GeTensorSerializeUtils::GetDtypeFromDescProto(proto_msg, dtype_);
648	  GeTensorSerializeUtils::GetShapeFromDescProto(proto_msg, shape_);
649	
650	  // get extension tensor desc metadata
651	  ext_meta_.SetSize(proto_msg->size());
652	  ext_meta_.SetWeightSize(proto_msg->weight_size());
653	  ext_meta_.SetReuseInput(proto_msg->reuse_input());
654	  ext_meta_.SetOutputTensor(proto_msg->output_tensor());
655	  if (kStrToDeviceMap.find(proto_msg->device_type()) != kStrToDeviceMap.end()) {
656	    ext_meta_.SetDeviceType(kStrToDeviceMap.at(proto_msg->device_type()));
657	  }
658	  ext_meta_.SetInputTensor(proto_msg->input_tensor());
659	  if (ge::IntegerChecker<uint32_t>::Compat(proto_msg->real_dim_cnt())) {
660	    ext_meta_.SetRealDimCnt(static_cast<uint32_t>(proto_msg->real_dim_cnt()));
661	  }
662	  if (ge::IntegerChecker<uint32_t>::Compat(proto_msg->reuse_input_index())) {
663	    ext_meta_.SetReuseInputIndex(static_cast<uint32_t>(proto_msg->reuse_input_index()));
664	  }
665	  ext_meta_.SetDataOffset(proto_msg->data_offset());
666	  ext_meta_.SetCmpsSize(proto_msg->cmps_size());
667	  ext_meta_.SetCmpsTab(proto_msg->cmps_tab());
668	  ext_meta_.SetCmpsTabOffset(proto_msg->cmps_tab_offset());
669	
670	  auto &attr_map = *(proto_msg->mutable_attr());
671	  const auto iter = attr_map.find(TENSOR_UTILS_ORIGIN_SHAPE_INITIALIZED);
672	  if (iter != attr_map.end()) {
673	    ext_meta_.SetOriginShapeInited(iter->second.b());
674	  }
675	
676	  // note that we deserialize attributes in implement of GeTensor constructor
677	}
