1048	graphStatus TensorDataImpl::SetData(const uint8_t *const data, const size_t size) {
1049	  if (size == 0UL) {
1050	    GELOGD("size is 0");
1051	    clear();
1052	    return GRAPH_SUCCESS;
1053	  }
1054	  if (data == nullptr) {
1055	    GELOGD("data addr is empty");
1056	    return GRAPH_SUCCESS;
1057	  }
1058	
1059	  if (MallocAlignedPtr(size) == nullptr) {
1060	    GELOGE(MEMALLOC_FAILED, "[Malloc][Memory] failed, size=%zu", size);
1061	    return GRAPH_FAILED;
1062	  }
1063	
1064	  size_t remain_size = size;
1065	  auto dst_addr = ge::PtrToValue(aligned_ptr_->MutableGet());
1066	  auto src_addr = ge::PtrToValue(data);
1067	  while (remain_size > SECUREC_MEM_MAX_LEN) {
1068	    if (memcpy_s(ge::ValueToPtr(dst_addr), SECUREC_MEM_MAX_LEN, ge::ValueToPtr(src_addr), SECUREC_MEM_MAX_LEN) != EOK) {
1069	      REPORT_INNER_ERR_MSG("E18888", "memcpy failed, size = %lu", SECUREC_MEM_MAX_LEN);
1070	      GELOGE(INTERNAL_ERROR, "[Memcpy][Data] failed, size = %lu", SECUREC_MEM_MAX_LEN);
1071	      return GRAPH_FAILED;
1072	    }
1073	    remain_size -= SECUREC_MEM_MAX_LEN;
1074	    dst_addr += SECUREC_MEM_MAX_LEN;
1075	    src_addr += SECUREC_MEM_MAX_LEN;
1076	  }
1077	  if (memcpy_s(ge::ValueToPtr(dst_addr), remain_size, ge::ValueToPtr(src_addr), remain_size) != EOK) {
1078	    REPORT_INNER_ERR_MSG("E18888", "memcpy failed, size=%zu", remain_size);
1079	    GELOGE(INTERNAL_ERROR, "[Memcpy][Data] failed, size=%zu", remain_size);
1080	    return GRAPH_FAILED;
1081	  }
