1327	GeTensorImpl::GeTensorImpl(const ProtoMsgOwner &proto_owner, proto::TensorDef *proto_msg)
1328	    : tensor_def_(proto_owner, proto_msg) {
1329	  // 这里后续改为反序列化接口调用，从proto恢复GeTensorDesc
1330	  desc_ = GeTensorDesc((proto_msg == nullptr) ? nullptr : proto_msg->mutable_desc());
1331	  tensor_data_ = TensorData();
1332	  if ((tensor_data_.impl_ != nullptr) && (desc_.impl_ != nullptr)) {
1333	    // 之前没有把TensorData上的proto变为GeTensorDesc，因为TensorData创建后不会修改，多个TensorData通过GeIrProto共享
1334	    // 但是！原本的语义是TensorData上的proto::TensorDescriptor与Tensor上的GeTensorDesc是共享的，当GeTensorDesc改造完
1335	    // 这种共享的能力就消失了，这会导致在GeTensor创建后，对GeTensorDesc的修改无法反应到TensorData上，看起来只能将TensorData
1336	    // 上的proto::TensorDescriptor修改为GeTensorDescImpl，并且需要与GeTensor的GeTensorDesc共享
1337	    tensor_data_.impl_->tensor_descriptor_ = desc_.impl_;
1338	  }
1339	
1340	  if (proto_msg != nullptr) {
1341	    if (proto_owner != nullptr) {
1342	      BuildAlignerPtrWithProtoData();
1343	    } else {
1344	      (void)tensor_data_.SetData(PtrToPtr<const char, const uint8_t>(proto_msg->data().data()),
1345	                                 proto_msg->data().size());
1346	    }
1347	  }
1348	}
