1354	void GeTensorImpl::BuildAlignerPtrWithProtoData() {
1355	  auto const proto_msg = tensor_def_.GetProtoMsg();
1356	  if ((proto_msg == nullptr) ||
1357	      (PtrToPtr<const char, const uint8_t>(proto_msg->data().data()) == tensor_data_.data())) {
1358	    return;
1359	  }
1360	  if (tensor_data_.impl_ == nullptr) {
1361	    return;
1362	  }
1363	
1364	  tensor_data_.impl_->length_ = proto_msg->data().size();
1365	  tensor_data_.impl_->aligned_ptr_.reset();
1366	  tensor_data_.impl_->aligned_ptr_ = AlignedPtr::BuildFromAllocFunc(
1367	      [&proto_msg](std::unique_ptr<uint8_t[], AlignedPtr::Deleter> &ptr) {
1368	        ptr.reset(const_cast<uint8_t *>(PtrToPtr<const char, const uint8_t>(proto_msg->data().data())));
1369	      },
1370	      [](const uint8_t *const ptr) { (void)ptr; });
1371	}
