1834	  if ((from.impl_ != nullptr) && (to.impl_ != nullptr)) {
1835	    if (from.impl_->tensor_def_.GetProtoOwner() != nullptr) {
1836	      // 这种场景下看原来的逻辑，已经没有什么是不是共享的了，所以直接改成了impl共享，幸好impl是shared ptr
1837	      // 但是之前似乎有个啥逻辑。是假定可以把shared ptr当成unique用的，得风暴下，记不得了
1838	      to.impl_ = from.impl_;
1839	    } else {
1840	      // share tensor_data, do not share tensor_desc, tensor_def is null
1841	      to.impl_->desc_ = from.impl_->desc_;
1842	      to.impl_->tensor_data_ = from.impl_->tensor_data_;
