1875	void TensorUtils::CopyTensor(const GeTensor &from, GeTensor &to) {
1876	  if (&from == &to) {
1877	    return;
1878	  }
1879	  if ((from.impl_ == nullptr) || (to.impl_ == nullptr)) {
1880	    return;
1881	  }
1882	  if (from.impl_->tensor_def_.GetProtoOwner() != nullptr) {
1883	    to.impl_->tensor_def_.CopyValueFrom(from.impl_->tensor_def_);
1884	    to.impl_->desc_.impl_ = GeTensorDesc(to.impl_->tensor_def_.GetProtoMsg()->mutable_desc()).impl_;
1885	    to.impl_->desc_.impl_->attrs_ = from.impl_->desc_.impl_->attrs_;
1886	    to.impl_->tensor_data_.impl_->tensor_descriptor_ = to.impl_->desc_.impl_;
1887	    to.BuildAlignerPtrWithProtoData();
1888	  } else {
1889	    // tensor_def is null, copy tensor_data, tensor_desc
1890	    to.impl_->desc_ = from.impl_->desc_;
1891	    (void)to.impl_->tensor_data_.SetData(from.impl_->tensor_data_);
1892	    to.impl_->tensor_data_.impl_->tensor_descriptor_ = to.impl_->desc_.impl_;
1893	  }
