1896	bool TensorUtils::IsShapeEqual(const GeShape &src, const GeShape &dst) {
1897	  GE_ASSERT_TRUE(src.GetDimNum() == dst.GetDimNum(), "src(%s) dims num is not equal to dst(%s) dim num.",
1898	                 src.ToString().c_str(), dst.ToString().c_str());
1899	  const auto src_dims = src.GetDims();
1900	  const auto dst_dims = dst.GetDims();
1901	  for (size_t i = 0UL; i < src_dims.size(); ++i) {
1902	    if ((src_dims[i] == -1) || (dst_dims[i] == -1)) {
1903	      GELOGW("src dim %d is %d, dst dim %d is %d, there has unknown shape.", i, src_dims[i], i, dst_dims[i]);
1904	      continue;
1905	    }
1906	    if (src_dims[i] != dst_dims[i]) {
1907	      GELOGW("src(%s) dim(%zu) = %ld is not equal to dst(%s) dim(%zu) = %ld.", src.ToString().c_str(), i, src_dims[i],
1908	             dst.ToString().c_str(), i, dst_dims[i]);
1909	      return false;
1910	    }
1911	  }
1912	  return true;
1913	}
