1916	  int32_t calc_type = 0;
1917	  (void)af::AttrUtils::GetInt(tensor_desc, ATTR_NAME_MEMORY_SIZE_CALC_TYPE, calc_type);
1918	
1919	  bool is_null_output = false;
1920	  (void)af::AttrUtils::GetBool(tensor_desc, ATTR_NAME_IS_NULL_OUTPUT, is_null_output);
1921	
1922	  if ((calc_type == MEMORY_SIZE_CALC_TYPE__ALWAYS_EMPTY) || is_null_output) {
1923	    GELOGI("Calc type: %d, output is null: %d", calc_type, static_cast<int32_t>(is_null_output));
1924	    return true;
1925	  }
1926	
1927	  return false;
1928	}
