30	static bool Int64MulNotOverflow(const int64_t a, const int64_t b) {
31	  if (a > 0) {
32	    if (b > 0) {
33	      if (a > (INT64_MAX / b)) {
34	        return false;
35	      }
36	    } else {
37	      if (b < (INT64_MIN / a)) {
38	        return false;
39	      }
40	    }
41	  } else {
42	    if (b > 0) {
43	      if (a < (INT64_MIN / b)) {
44	        return false;
45	      }
46	    } else {
47	      if ((a != 0) && (b < (INT64_MAX / a))) {
