55	class TensorDescValue {
56	 public:
57	  TensorDescValue() = default;
58	  ~TensorDescValue() = default;
59	  TensorDescValue(const TensorDescValue &other) {
60	    if ((other.const_data_len_ == 0U) || (other.const_data_buffer_ == nullptr)) {
61	      return;
62	    }
63	    if (!TensorDescValue::CloneValue(this->const_data_buffer_, other.const_data_buffer_, other.const_data_len_)) {
64	      return;
65	    }
66	    this->const_data_len_ = other.const_data_len_;
67	    return;
68	  }
69	  TensorDescValue &operator=(const TensorDescValue &other) {
70	    if ((&other == this) || (other.const_data_len_ == 0U) || (other.const_data_buffer_ == nullptr)) {
71	      return *this;
72	    }
73	    if (!TensorDescValue::CloneValue(this->const_data_buffer_, other.const_data_buffer_, other.const_data_len_)) {
74	      return *this;
75	    }
76	    this->const_data_len_ = other.const_data_len_;
77	    return *this;
78	  }
79	
80	 private:
81	  std::unique_ptr<uint8_t[]> const_data_buffer_ = nullptr;
82	  size_t const_data_len_ = 0U;
83	
84	  static bool CloneValue(std::unique_ptr<uint8_t[]> &dst, const std::unique_ptr<uint8_t[]> &src,
85	                         const std::size_t len) {
86	    dst = ComGraphMakeUnique<uint8_t[]>(len);
87	    if (dst == nullptr) {
88	      return false;
89	    }
90	    size_t remain_size = len;
91	    auto dst_addr = ge::PtrToValue(static_cast<void *>(dst.get()));
92	    auto src_addr = ge::PtrToValue(static_cast<void *>(src.get()));
93	    while (remain_size > SECUREC_MEM_MAX_LEN) {
94	      if (memcpy_s(ge::ValueToPtr(dst_addr), SECUREC_MEM_MAX_LEN, ge::ValueToPtr(src_addr), SECUREC_MEM_MAX_LEN) !=
95	          EOK) {
96	        return false;
97	      }
98	      remain_size -= SECUREC_MEM_MAX_LEN;
99	      dst_addr += SECUREC_MEM_MAX_LEN;
100	      src_addr += SECUREC_MEM_MAX_LEN;
101	    }
102	    if ((remain_size != 0U) &&
103	        (memcpy_s(ge::ValueToPtr(dst_addr), remain_size, ge::ValueToPtr(src_addr), remain_size) != EOK)) {
104	      return false;
105	    }
106	    return true;
107	  }
108	  friend class TensorDesc;
109	};
