141	 public:
142	  TensorImpl() = default;
143	  ~TensorImpl() = default;
144	
145	  explicit TensorImpl(const TensorDesc &tensor_desc) : ge_tensor(TensorAdapter::TensorDesc2GeTensorDesc(tensor_desc)) {}
146	  TensorImpl(const TensorDesc &tensor_desc, const std::vector<uint8_t> &data)
147	      : ge_tensor(TensorAdapter::TensorDesc2GeTensorDesc(tensor_desc), data) {}
148	  TensorImpl(const TensorDesc &tensor_desc, const uint8_t *const data, const size_t size)
149	      : ge_tensor(TensorAdapter::TensorDesc2GeTensorDesc(tensor_desc), data, size) {}
