151	      : ge_tensor(TensorAdapter::TensorDesc2GeTensorDesc(tensor_desc), std::move(data)) {}
152	
153	  graphStatus SetData(const std::string &data) {
154	    if (!data.empty()) {
155	      /// Extra 16 bytes store string head
156	      /// Extra 1 byte store '\0'
157	      const size_t total_size = data.size() + sizeof(StringHead) + 1U;
158	      const std::unique_ptr<char_t[]> buff = ComGraphMakeUnique<char_t[]>(total_size);
159	      if (buff == nullptr) {
160	        REPORT_INNER_ERR_MSG("E18888", "allocate string raw data buff failed, size:%zu", total_size);
161	        GELOGE(ge::GRAPH_FAILED, "[New][Buffer] allocate string raw data buff failed");
162	        return ge::GRAPH_FAILED;
163	      }
164	      StringHead *const string_head = PtrToPtr<char_t, StringHead>(buff.get());
165	      // Front 8 bytes store pointer of string
166	      char_t *const raw_data = PtrToPtr<void, char_t>(
167	          ge::ValueToPtr(ge::PtrToValue(PtrToPtr<char_t, void>(buff.get())) + sizeof(*string_head)));
168	      string_head->addr = static_cast<int64_t>(sizeof(StringHead));
169	      string_head->len = static_cast<int64_t>(data.size());
170	      const int32_t memcpy_ret = memcpy_s(raw_data, total_size - sizeof(StringHead), data.c_str(), data.size() + 1U);
171	      if (memcpy_ret != EOK) {
172	        REPORT_INNER_ERR_MSG("E18888", "memcpy data failed, ret:%d, size:%zu.", memcpy_ret, data.size() + 1U);
173	        GELOGE(ge::GRAPH_FAILED, "[Copy][Data] failed, ret:%d", memcpy_ret);
174	        return ge::GRAPH_FAILED;
175	      }
176	      (void)ge_tensor.SetData(PtrToPtr<char_t, const uint8_t>(buff.get()), total_size);
177	      return GRAPH_SUCCESS;
178	    }
179	    return ge::GRAPH_FAILED;
180	  }
181	
182	  graphStatus SetData(const std::vector<std::string> &data) {
183	    if (data.empty()) {
184	      REPORT_INNER_ERR_MSG("E18888", "there is no data, please check the input variable");
185	      GELOGE(ge::GRAPH_FAILED, "[Check][Param] there is no data, please check the input variable");
186	      return ge::GRAPH_FAILED;
187	    }
188	    size_t total_size = 0U;
189	    total_size = std::accumulate(data.begin(), data.end(), total_size, [](size_t total, const std::string &str) {
190	      /// Extra 16 bytes store string head
191	      /// Extra 1 byte store '\0'
192	      total += str.size() + sizeof(StringHead) + 1U;
193	      return total;
194	    });
195	
196	    const std::unique_ptr<char_t[]> buff = ComGraphMakeUnique<char_t[]>(total_size);
197	    if (buff == nullptr) {
198	      REPORT_INNER_ERR_MSG("E18888", "allocate string raw data buff failed, size:%zu", total_size);
199	      GELOGE(ge::GRAPH_FAILED, "[New][Buffer] allocate string raw data buff failed");
200	      return ge::GRAPH_FAILED;
201	    }
202	    // Front some bytes store head of each string
203	    StringHead *const string_head = PtrToPtr<char_t, StringHead>(buff.get());
204	    uint64_t raw_data = ge::PtrToValue(static_cast<void *>(buff.get())) + (data.size() * sizeof(*string_head));
205	    uint64_t ptr_size = data.size() * sizeof(StringHead);
206	    for (size_t i = 0U; i < data.size(); ++i) {
207	      PtrAdd<StringHead>(string_head, data.size(), i)->addr = static_cast<int64_t>(ptr_size);
208	      PtrAdd<StringHead>(string_head, data.size(), i)->len = static_cast<int64_t>(data[i].size());
209	      if (total_size < ptr_size) {
210	        REPORT_INNER_ERR_MSG("E18888", "Subtraction invalid, total_size:%zu, ptr_size:%" PRIu64, total_size, ptr_size);
211	        GELOGE(ge::GRAPH_FAILED, "[Check][Param] Subtraction invalid, total_size: %zu, ptr_size: %" PRIu64, total_size,
212	               ptr_size);
213	        return ge::GRAPH_FAILED;
214	      }
215	      const int32_t memcpy_ret =
216	          memcpy_s(ge::ValueToPtr(raw_data), total_size - ptr_size, data[i].c_str(), data[i].size() + 1U);
217	      GE_CHK_BOOL_RET_STATUS(memcpy_ret == EOK, GRAPH_FAILED, "copy data failed");
218	      raw_data += (data[i].size() + 1U);
219	      ptr_size += (data[i].size() + 1U);
220	    }
221	
222	    (void)ge_tensor.SetData(PtrToPtr<char_t, const uint8_t>(buff.get()), total_size);
223	    return GRAPH_SUCCESS;
224	  }
