302	int64_t Shape::GetShapeSize() const {
303	  if (impl_ != nullptr) {
304	    if (impl_->dims_.empty()) {
305	      return 0;
306	    }
307	    int64_t size = 1;
308	    for (const auto i : impl_->dims_) {
309	      if ((i == UNKNOWN_DIM_NUM) || (i == UNKNOWN_DIM)) {
310	        return UNKNOWN_DIM_SIZE;
311	      }
312	
313	      if (!Int64MulNotOverflow(size, i)) {
314	        REPORT_INNER_ERR_MSG("E18888", "mul overflow: %" PRId64 ", %" PRId64, size, i);
315	        GELOGE(ge::GRAPH_FAILED, "[Check][Overflow] mul overflow: %" PRId64 ", %" PRId64, size, i);
316	        size = 0;
317	        return size;
318	      }
319	      size *= i;
320	    }
321	    return size;
322	  }
323	  return 0;
324	}
