592	static void CheckTensorParam(const uint64_t shape_size, const DataType data_type, const size_t data_size) {
593	  uint32_t type_length;
594	  const bool ret = TypeUtils::GetDataTypeLength(data_type, type_length);
595	  if (!ret) {
596	    GELOGW("[Create][Tensor] Datatype %d not found.", data_type);
597	  }
598	
599	  if (ret && ((shape_size != 0U) || (data_size != type_length))) {
600	    if ((type_length != 0U) && ((UINT64_MAX / type_length) < shape_size)) {
601	      GELOGW("[Create][Tensor] Calculate size failed, as mul overflow: %" PRIu64 " * %" PRIu32, shape_size,
602	             type_length);
603	    } else {
604	      if ((shape_size * type_length) != data_size) {
605	        GELOGW("[Create][Tensor] Tensor length not equal: shape_byte_size=%" PRIu64 ", dt_type=%s, data_size=%zu.",
606	               shape_size * type_length, TypeUtils::DataTypeToSerialString(data_type).c_str(), data_size);
607	      }
608	    }
609	  }
610	}
