764	graphStatus Tensor::IsValid() {
765	  const uint64_t shape_size = static_cast<uint64_t>(GetTensorDesc().GetShape().GetShapeSize());
766	  const DataType data_type = GetTensorDesc().GetDataType();
767	  uint32_t type_length;
768	  const bool ret = TypeUtils::GetDataTypeLength(data_type, type_length);
769	  if (!ret) {
770	    GELOGW("[Check][Tensor] Datatype %d not found.", data_type);
771	    return GRAPH_SUCCESS;
772	  }
773	
774	  const size_t data_size = GetSize();
775	  if (data_type == DT_STRING) {
776	    return GRAPH_SUCCESS;
777	  }
778	
779	  if ((shape_size != 0U) || (data_size != type_length)) {
780	    if ((type_length != 0U) && ((UINT64_MAX / type_length) < shape_size)) {
781	      GELOGW("[Check][Tensor] Calculate size failed, as mul overflow: %" PRIu64 " * %" PRIu32, shape_size, type_length);
782	    } else {
783	      if ((shape_size * type_length) != data_size) {
784	        GELOGW("[Check][Tensor] Tensor length not equal: shape_byte_size=%" PRIu64 ", dt_type=%s, data_size=%zu.",
785	               shape_size * type_length, TypeUtils::DataTypeToSerialString(data_type).c_str(), data_size);
786	        return ge::GRAPH_FAILED;
787	      }
788	    }
789	  }
790	
791	  return GRAPH_SUCCESS;
