259	  bool SetContiguousView(const std::vector<Axis> &axes) {
260	    GE_ASSERT_NOTNULL(axis, "output tensor should bind to API by API function or by AutoOffset");
261	    GE_ASSERT_NOTNULL(repeats, "output tensor should bind to API by API function or by AutoOffset");
262	    GE_ASSERT_NOTNULL(strides, "output tensor should bind to API by API function or by AutoOffset");
263	    std::vector<AxisId> axes_ids;
264	    std::vector<Expression> tmp_repeats;
265	    std::vector<Expression> tmp_strides;
266	    axes_ids.reserve(axes.size());
267	    tmp_repeats.reserve(axes.size());
268	    tmp_strides.reserve(axes.size());
269	
270	    std::for_each(axes.rbegin(), axes.rend(), [&axes_ids, &tmp_repeats, &tmp_strides](const Axis &tmp_axis) {
271	      if (tmp_strides.empty()) {
272	        tmp_strides.emplace_back(sym::kSymbolOne);
273	      } else {
274	        tmp_strides.emplace_back(*tmp_repeats.rbegin() * *tmp_strides.rbegin());
275	      }
276	      tmp_repeats.emplace_back(tmp_axis.size);
277	      axes_ids.emplace_back(tmp_axis.id);
278	    });
279	    std::reverse(axes_ids.begin(), axes_ids.end());
280	    std::reverse(tmp_repeats.begin(), tmp_repeats.end());
281	    std::reverse(tmp_strides.begin(), tmp_strides.end());
282	
283	    *axis = axes_ids;
284	    *repeats = tmp_repeats;
285	    *strides = tmp_strides;
286	    return true;
287	  }
