502	template <uint32_t INPUT_INDEX>
503	class AscOpDynamicInput {
504	 public:
505	  explicit AscOpDynamicInput(Operator *op) : op_(op) {}
506	  AscOpDynamicInput<INPUT_INDEX> &operator=(const std::initializer_list<AscOpOutput> &outputs) {
507	    return AssignImpl(outputs);
508	  }
509	  AscOpDynamicInput<INPUT_INDEX> &operator=(const std::vector<AscOpOutput> &outputs) {
510	    return AssignImpl(outputs);
511	  }
512	
513	 private:
514	  template <typename Container>
515	  AscOpDynamicInput<INPUT_INDEX> &AssignImpl(const Container &outputs) {
516	    if (op_ == nullptr) {
517	      GELOGE(FAILED, "op_ in null");
518	      return *this;
519	    }
520	    if (inited_) {
521	      AscendString op_name;
522	      (void)op_->GetName(op_name);
523	      GELOGE(FAILED, "It is not allowed to set the dynamic input repeatedly, node:[%s].", op_name.GetString());
524	      return *this;
525	    }
526	    const size_t input_nums = outputs.size();
527	    SetDynamicInputNumByIrIndex(*this->op_, INPUT_INDEX, input_nums);
528	    size_t idx = 0UL;
529	    for (const auto &output : outputs) {
530	      if (output.op_ == nullptr) {
531	        GELOGE(FAILED, "Src tensor is null");
532	        return *this;
533	      }
534	      LinkByIrIndex(*output.op_, output.output_index, *this->op_, INPUT_INDEX, idx++);
535	    }
536	    inited_ = true;
537	    return *this;
538	  }
539	  Operator *op_{nullptr};
540	  bool inited_{false};
541	};
